 *
 * 设计说明：
 * - model-io 由 adapters/model/runner-debug.ts 落盘；一个 session 一个
 *   `model-io-<sanitizedSessionId>.jsonl`。
 * - Knorvia Agent 把 taskId 当作 sessionId（见 taskServiceAdapter），所以这里只读取
 *   该 session 的单文件，并按 `record.sessionId === taskId` 精确匹配。
 */
export declare function readModelTrajectory(taskId: string, limit?: number): Promise<KnorviaModelTrajectory>;


export type KnorviaModelTrajectoryContentPart = {
    kind: "text";
    text: string;
} | {
    kind: "reasoning";
    text: string;
} | {
    kind: "tool-call";
    toolCallId?: string;
    toolName: string;
    input?: unknown;
} | {
    kind: "tool-result";
    toolCallId?: string;
    toolName?: string;
    output?: unknown;
} | {
    kind: "image";
    mediaType?: string;
} | {
    kind: "unknown";
    raw: unknown;
};

